(function(){if(!window.cncI18n)return;cncI18n.add({exact:{"Kurs 1 och 3: raka linjer och bågar.": "Courses 1 and 3: straight lines and arcs.", "Kurs 1. Kurs 3 behövs för helix.": "Course 1. Course 3 is needed for the helix.", "Kurs 1, 4 och 6.": "Courses 1, 4 and 6.", "Kurs 1 och 6. Lektionerna förklarar S och F från början.": "Courses 1 and 6. The lessons explain S and F from the start.", "Kurs 4 och 6: radiekompensering och djup.": "Courses 4 and 6: cutter compensation and depth.", "Kurs 1.": "Course 1.", "Kurs 8: borrcykler.": "Course 8: drilling cycles.", "Kurs 2 och 6: G91 och djup.": "Courses 2 and 6: G91 and depth.", "De tidigare kurserna, eller i alla fall de flesta av dem.": "The earlier courses, or at least most of them.", "Du ska kunna G02 och G03 (kurs 3) och radiekompensering med G41 och G40 (kurs 4). Alla lektioner använder D2, pinnfräs Ø10 med radien 5 mm.": "You should know G02 and G03 (course 3) and cutter compensation with G41 and G40 (course 4). All lessons use D2, end mill Ø10 with a 5 mm radius."}});})();
